package com.example.library.entity;

import jakarta.persistence.*;

/**
 * Book Entity - Represents a book in the Digital Library Management System
 * 
 * This class maps to the "books" table in PostgreSQL database.
 * Each book has an ID, title, author, category, and availability information.
 * 
 * Annotations explained:
 * @Entity - Marks this class as a JPA entity (maps to database table)
 * @Table - Specifies the table name in database
 * @Id - Marks the field as primary key
 * @GeneratedValue - Auto-generates unique ID values
 */
@Entity
@Table(name = "books")
public class Book {

    /**
     * Unique identifier for each book
     * Auto-generated by the database (SEQUENCE strategy)
     */
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long bookId;

    /**
     * Title of the book
     * Cannot be null
     */
    @Column(nullable = false)
    private String title;

    /**
     * Author of the book
     * Cannot be null
     */
    @Column(nullable = false)
    private String author;

    /**
     * Category/Genre of the book (e.g., Programming, AI, Database, etc.)
     */
    private String category;

    /**
     * Number of copies available in the library
     * Default value is 1 if not specified
     */
    private int availableCount = 1;

    // ==================== Constructors ====================

    /**
     * No-argument constructor
     * Required by JPA for entity instantiation
     */
    public Book() {
    }

    /**
     * Constructor with all fields
     * Used for creating new book instances
     * 
     * @param title Title of the book
     * @param author Author of the book
     * @param category Category/Genre of the book
     * @param availableCount Number of available copies
     */
    public Book(String title, String author, String category, int availableCount) {
        this.title = title;
        this.author = author;
        this.category = category;
        this.availableCount = availableCount;
    }

    // ==================== Getters & Setters ====================

    /**
     * Get book ID
     * @return bookId - The unique identifier of the book
     */
    public Long getBookId() {
        return bookId;
    }

    /**
     * Set book ID
     * @param bookId - The unique identifier to set
     */
    public void setBookId(Long bookId) {
        this.bookId = bookId;
    }

    /**
     * Get book title
     * @return title - The title of the book
     */
    public String getTitle() {
        return title;
    }

    /**
     * Set book title
     * @param title - The title to set
     */
    public void setTitle(String title) {
        this.title = title;
    }

    /**
     * Get book author
     * @return author - The author of the book
     */
    public String getAuthor() {
        return author;
    }

    /**
     * Set book author
     * @param author - The author to set
     */
    public void setAuthor(String author) {
        this.author = author;
    }

    /**
     * Get book category
     * @return category - The category/genre of the book
     */
    public String getCategory() {
        return category;
    }

    /**
     * Set book category
     * @param category - The category/genre to set
     */
    public void setCategory(String category) {
        this.category = category;
    }

    /**
     * Get available count
     * @return availableCount - Number of available copies
     */
    public int getAvailableCount() {
        return availableCount;
    }

    /**
     * Set available count
     * @param availableCount - Number of available copies to set
     */
    public void setAvailableCount(int availableCount) {
        this.availableCount = availableCount;
    }

    // ==================== Additional Methods ====================

    /**
     * String representation of the Book object
     * Useful for logging and debugging
     * 
     * @return String containing book information
     */
    @Override
    public String toString() {
        return "Book{" +
                "bookId=" + bookId +
                ", title='" + title + '\'' +
                ", author='" + author + '\'' +
                ", category='" + category + '\'' +
                ", availableCount=" + availableCount +
                '}';
    }

}
